var o=[{title:`Primeiro, confirme que é uma estagnação`,text:`Uma sessão dececionante não é uma estagnação. Compare várias semanas em condições semelhantes: o mesmo exercício, carga, amplitude e esforço. Alterações no equipamento, no sono ou na técnica podem fazer os seus números parecerem piores mesmo quando a sua condição física não está a descer. Registe detalhes suficientes para distinguir uma tendência real das oscilações de dia para dia.`},{title:`Verifique o essencial`,text:`Concluiu as suas sessões? A resistência continuou a ser um desafio e recuperou entre treinos? O volume era o certo para si? Por vezes a carga de trabalho é demasiado baixa e por vezes é mais alta do que o necessário. Um levantamento também pode estagnar porque não praticou esse movimento com regularidade, enquanto os músculos ainda se estão a adaptar.`},{title:`Faça uma alteração útil`,text:`Se concluir as repetições com facilidade, acrescente um pouco de carga ou use a dupla progressão. Se a fadiga estiver a acumular-se e o desempenho a descer, reduza as séries difíceis durante algum tempo ou reorganize o seu horário. Se um movimento deixou de melhorar, experimente uma alteração de técnica ou uma variação muito próxima e mantenha o resto do programa como está.`},{title:`Ganhos mais lentos com o tempo`,text:`Os iniciantes costumam melhorar depressa, em parte porque estão a aprender os movimentos. Os praticantes experientes progridem mais devagar e em passos mais pequenos. O crescimento muscular demora a medir, por isso uma balança sem alterações ou um único teste de desempenho não prova que o seu treino falhou. Peça a um médico que avalie a fadiga que não consegue explicar ou outros sintomas de saúde que persistam.`},{title:`Usar o TrainUp`,text:`O Histórico mostra os seus treinos, o seu esforço médio e um gráfico das últimas 4 semanas, o que pode ajudar a detetar uma possível estagnação. O TrainUp nunca altera o seu plano com base em menos de 3 treinos, por isso um dia difícil não desencadeia um programa novo. Faça pequenos ajustes e volte a verificar depois de várias sessões.`}];var s=[{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: segurança e fundamentos do treino de resistência`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Orientações do ACSM sobre o modelo de progressão`,url:`https://pubmed.ncbi.nlm.nih.gov/11828249/`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};